<?php get_header(); $author=get_queried_object(); ?><main id="main-content" class="slateframe-main"><header class="slateframe-page-header"><div class="slateframe-shell"><h1 class="slateframe-page-title"><?php echo esc_html(get_the_author_meta('display_name',$author->ID)); ?></h1><?php if(get_the_author_meta('description',$author->ID)):?><p><?php echo esc_html(get_the_author_meta('description',$author->ID)); ?></p><?php endif;?></div></header><div class="slateframe-shell slateframe-grid"><?php while(have_posts()):the_post();?><article <?php post_class('slateframe-card'); ?>><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php endwhile;?></div><div class="slateframe-shell"><?php slateframe_pagination(); ?></div></main><?php get_footer(); ?>